import re
wb=load_workbook('input.xlsx', data_only=False)
ws=wb['8. Income Statement']
for row in ws.iter_rows(min_row=1, max_row=ws.max_row):
    form={}
    for c in row:
        if isinstance(c.value,str) and c.value.startswith('='):
            form[c.column_letter]=c.value
    if not form: continue
    # For each cell in E-P, parse references to external sheet and row
    # Simpler: flag if same 'operand expression' has a numeric constant 1 with sign multiply/add, and if source row in formula differs from E cell source row
    def refs(v):
        # return set of sheet:columnrow matches
        out=set()
        for m in re.findall(r"(?:'[^']*'|\w+)!(\$?[A-Z]+)(\$?\d+)", v):
            out.add((m[0].replace('$',''), int(m[1].replace('$',''))))
        # also local refs like F41
        for m in re.findall(r"(^|[^A-Z])(\$?[A-Z]{1,2})(\$?\d+)", v):
            col=m[2]; ro=m[3]
            if re.fullmatch(r'[A-Z]{1,2}', col) and m[2].isalpha() and m[3].isdigit():
                out.add((col.replace('$',''), int(ro.replace('$',''))))
        return out
    erows=[]
    if 'E' in form: erows=refs(form['E'])
    suspicious=[]
    for col in 'FGHIJKLMNOP':
        v=form.get(col)
        if not v: continue
        if '+1' in v or '-1' in v or '*1' in v or '1+' in v or '1-' in v:
            suspicious.append((col,v,'numeric1'))
        rows=refs(v)
        # If E formula has external refs and current cell has same ref set but row different => defect
        if erows and rows:
            # compare only same sheet prefixes? just print if row numbers differ from E but no local preceding refs
            if rows and rows != erows:
                suspicious.append((col,v,'refs '+str(rows)+' vs '+str(erows)))
    if suspicious:
        print('ROW', row[0].row)
        for s in suspicious: print(' ', s)
